add_action( 'admin_notices', 'perfectpixel_min_words_notice' );

function perfectpixel_min_words_limit() {
	return max( 0, (int) '{{min_word_count}}' );
}

function perfectpixel_min_words_applies( $post_type ) {
	if ( 'yes' === strtolower( trim( '{{min_word_count_admins_exempt}}' ) ) && current_user_can( 'manage_options' ) ) {
		return false;
	}
	$types = array_filter( array_map( 'trim', explode( ',', '{{min_word_count_post_types}}' ) ) );
	return perfectpixel_min_words_limit() > 0 && in_array( $post_type, $types, true );
}

// Counts words in any script (Greek included), ignoring HTML, block comments and shortcodes.
function perfectpixel_min_words_count( $content ) {
	$text = wp_strip_all_tags( strip_shortcodes( (string) $content ) );
	$text = trim( html_entity_decode( $text, ENT_QUOTES, 'UTF-8' ) );
	return '' === $text ? 0 : count( preg_split( '/\s+/u', $text ) );
}

function perfectpixel_min_words_message( $count ) {
	return sprintf( 'Το άρθρο έχει %1$d λέξεις. Για δημοσίευση χρειάζονται τουλάχιστον %2$d.', $count, perfectpixel_min_words_limit() );
}

// Block editor: refuse the save with an error message.
function perfectpixel_min_words_rest( $prepared, $request ) {
	if ( is_wp_error( $prepared ) || false !== strpos( (string) $request->get_route(), '/autosaves' ) ) {
		return $prepared;
	}
	$existing  = ! empty( $prepared->ID ) ? get_post( $prepared->ID ) : null;
	$post_type = isset( $prepared->post_type ) ? $prepared->post_type : ( $existing ? $existing->post_type : '' );
	$status    = isset( $prepared->post_status ) ? $prepared->post_status : ( $existing ? $existing->post_status : 'draft' );
	if ( ! in_array( $status, array( 'publish', 'future' ), true ) || ! perfectpixel_min_words_applies( $post_type ) ) {
		return $prepared;
	}
	$content = isset( $prepared->post_content ) ? $prepared->post_content : ( $existing ? $existing->post_content : '' );
	$count   = perfectpixel_min_words_count( $content );
	if ( $count < perfectpixel_min_words_limit() ) {
		return new WP_Error( 'perfectpixel_min_words', perfectpixel_min_words_message( $count ), array( 'status' => 400 ) );
	}
	return $prepared;
}

// Classic editor and Quick Edit: keep the post as a draft.
function perfectpixel_min_words_classic( $data, $postarr ) {
	if ( ! is_admin() || ( defined( 'REST_REQUEST' ) && REST_REQUEST ) || ( defined( 'DOING_AUTOSAVE' ) && DOING_AUTOSAVE ) ) {
		return $data;
	}
	if ( ! in_array( $data['post_status'], array( 'publish', 'future' ), true ) || ! perfectpixel_min_words_applies( $data['post_type'] ) ) {
		return $data;
	}
	$count = perfectpixel_min_words_count( wp_unslash( $data['post_content'] ) );
	if ( $count < perfectpixel_min_words_limit() ) {
		$data['post_status']                       = 'draft';
		$GLOBALS['perfectpixel_min_words_blocked'] = $count;
	}
	return $data;
}

function perfectpixel_min_words_redirect( $location ) {
	if ( isset( $GLOBALS['perfectpixel_min_words_blocked'] ) ) {
		$location = add_query_arg( 'perfectpixel_min_words', (int) $GLOBALS['perfectpixel_min_words_blocked'], remove_query_arg( 'message', $location ) );
	}
	return $location;
}

function perfectpixel_min_words_notice() {
	if ( isset( $_GET['perfectpixel_min_words'] ) ) {
		printf( '<div class="notice notice-error"><p>%s %s</p></div>', esc_html( perfectpixel_min_words_message( absint( $_GET['perfectpixel_min_words'] ) ) ), esc_html( 'Αποθηκεύτηκε ως πρόχειρο.' ) );
	}
}
